package com.acttub.actingapi.security;
import static org.assertj.core.api.Assertions.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*; import org.junit.jupiter.api.Test;
class FixedWindowRateLimiterTest {@Test void concurrentRequestsAllowExactlySixty()throws Exception{FixedWindowRateLimiter limiter=new FixedWindowRateLimiter(()->1L);ExecutorService pool=Executors.newFixedThreadPool(20);try{var start=new CountDownLatch(1);var allowed=new AtomicInteger();var tasks=java.util.stream.IntStream.range(0,100).mapToObj(i->(Callable<Void>)()->{start.await();if(limiter.allow("same",60))allowed.incrementAndGet();return null;}).toList();var futures=tasks.stream().map(pool::submit).toList();start.countDown();for(var f:futures)f.get();assertThat(allowed).hasValue(60);}finally{pool.shutdownNow();}}
    @Test void spacesAreIndependentAndWindowResets(){AtomicLong now=new AtomicLong();FixedWindowRateLimiter limiter=new FixedWindowRateLimiter(now::get);assertThat(limiter.allow("user",1)).isTrue();assertThat(limiter.allow("auth-ip:127.0.0.1",1)).isTrue();assertThat(limiter.allow("user",1)).isFalse();now.set(60_000_000_000L);assertThat(limiter.allow("user",1)).isTrue();}
    // 하네스 제어는 contract 빈에서만 산다. 운영 빈이 조용히 실행하면 방어가 호출처 하나에만 걸린다.
    @Test void harnessControlLivesOnlyOnTheContractBean(){FixedWindowRateLimiter production=new FixedWindowRateLimiter(()->1L);assertThatThrownBy(production::reset).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->production.advanceContractClock(1L)).isInstanceOf(IllegalStateException.class);FixedWindowRateLimiter contract=new FixedWindowRateLimiter(()->1L,true);assertThat(contract.allow("k",1)).isTrue();assertThat(contract.allow("k",1)).isFalse();contract.reset();assertThat(contract.allow("k",1)).isTrue();}}
